class Theme:
    current_theme = Colors.TYPE
    bus = Colors.BUS
    train = Colors.TRAIN
    ferry = Colors.FERRY
    all = Colors.ALL

    @staticmethod
    def select(index: int):
        if index == 0:
            Theme.current_theme = Theme.bus

        elif index == 1:
            Theme.current_theme = Theme.train

        elif index == 2:
            Theme.current_theme = Theme.ferry

        elif index == 3:
            Theme.current_theme = Theme.all

        else:
            return

        Colors.TYPE = Theme.current_theme

        Style.LABEL_TIME.set_text_color(lv.color_hex(Colors.TYPE))
