    @staticmethod
    def load_saved_files(
        filepaths: str | tuple[str, ...]
    ) -> None | Exception:

        filepaths_is_str = isinstance(filepaths, str)
        filepaths_is_tuple = isinstance(filepaths, tuple)
        exception = None

        iterations = 1

        if filepaths_is_str:
            iterations = 1

        elif filepaths_is_tuple:
            iterations = len(filepaths)

        else:
            return AttributeError

        for i in range(iterations):
            try:
                pass

            except Exception as e:
                exception = e

            finally:
                pass

        return exception


    @staticmethod
    def get_saved_default_settings():
        return Settings.saved_default_settings

    @staticmethod
    def save_to_files(
        filepaths: str | tuple[str, ...]
    ) -> None | Exception:

        filepaths_is_str = isinstance(filepaths, str)
        filepaths_is_tuple = isinstance(filepaths, tuple)
        exception = None

        iterations = 1

        if filepaths_is_str:
            iterations = 1

        elif filepaths_is_tuple:
            iterations = len(filepaths)

        else:
            return TypeError

        for i in range(iterations):
            try:
                pass

            except Exception as e:
                exception = e

            finally:
                pass

        return exception

    @staticmethod
    def save_to_default_settings(
        new_default_settings: dict
    ) -> None | Exception:

        Settings.saved_default_settings = new_default_settings
        exception = None
        exception = Settings.save_to_files(
            Settings.filepath_saved_default_settings
        )

        return exception


